insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('porepressure', 'intermediate', 'module', 'm01-from-departure-to-pressure', 1, 'What does the Professional tier add to the Associate tier''s work?', '["It converts the sonic''s departure from the trend into pressure at every sample.", "It builds the hydrostatic and overburden columns of the reference frame.", "It converts the finished pressures into the equivalent mud weights the drilling engineer specifies mud with.", "It fits the compaction trend through the twelve shale picks."]'::jsonb, 0, 'The Associate tier built the frame and the trend; the Expert tier converts to mud units. This tier runs the Eaton inversion that turns departure into pressure.'),
  ('porepressure', 'intermediate', 'module', 'm01-from-departure-to-pressure', 2, 'In Eaton''s relation PP = S - (S - Ph) r^n, what is the quantity S - Ph?', '["The overpressure the well is currently holding at that depth, before the exponent amplifies it.", "The stress budget: the effective stress a normally pressured rock would carry there.", "The margin the fracture pressure keeps above the pore pressure at that depth.", "The pressure a balanced mud column referenced to sea level exerts at that depth."]'::jsonb, 1, 'S - Ph is the gap between overburden and hydrostatic, which is both the normal effective stress and the most overpressure the depth could hold.'),
  ('porepressure', 'intermediate', 'module', 'm01-from-departure-to-pressure', 3, 'What is the stress budget at total depth on the golden well?', '["41.408579625 MPa, the hydrostatic value there.", "91.12306695073282 MPa, the value the density integration reaches there.", "49.714487325732826 MPa, the overburden less the hydrostatic.", "35.523412418439044 MPa, as computed in the worked example at 3000 m."]'::jsonb, 2, 'The budget is the overburden less the hydrostatic: 91.12306695073282 minus 41.408579625. The other values are the frame curves themselves and the 3000 m budget.'),
  ('porepressure', 'intermediate', 'module', 'm01-from-departure-to-pressure', 4, 'The graded overpressure at TD, 6 MPa, is what fraction of the TD stress budget?', '["About 12 percent.", "About 6 percent, matching the 6 MPa figure.", "About 50 percent, half the budget handed to the fluid.", "About 25 percent, a quarter of the gap."]'::jsonb, 0, '6 of 49.714487325732826 MPa is 12.07 percent. The method allocates a fraction of the budget to the fluid; this well hands over about an eighth of it at TD.'),
  ('porepressure', 'intermediate', 'module', 'm01-from-departure-to-pressure', 5, 'Why can this synthetic well demonstrate that the prognosis machinery is sound?', '["Because its trend was fitted with zero residuals through its twelve picks.", "Because its pressures were encoded into its transit times, so the answer is known in advance.", "Because its density log was constructed with far more precision than a wireline tool achieves.", "Because its overpressure is gentle enough that method errors stay smaller than the tolerances."]'::jsonb, 1, 'A 4 kPa per metre ramp was written into the sonic below 2500 m. Running the method forward must recover it, which gives the tier an answer key no real well has.'),
  ('porepressure', 'intermediate', 'module', 'm01-from-departure-to-pressure', 6, 'Which ingredients of Eaton''s relation are empirical rather than derived physics?', '["The trapezoidal overburden integration and the two-part hydrostatic column.", "Terzaghi''s partition of total stress between grains and fluid.", "The claim that a compacting shale''s velocity responds to the effective stress it carries.", "The power-law form of the ratio term, and the exponent n itself."]'::jsonb, 3, 'Terzaghi and the frame are physics and arithmetic; velocity responding to stress is established rock physics. The specific power law and n = 3 were calibrated to Gulf of Mexico wells.'),
  ('porepressure', 'intermediate', 'module', 'm01-from-departure-to-pressure', 7, 'What state is the golden well''s sonic in above 2500 m, by construction?', '["Exactly on the well''s own header trend at every sample.", "Slightly slow against the header trend, within log noise.", "Exactly on the trend fitted to the twelve picks rather than on the header trend.", "Slightly fast against the trend, as cementation would read."]'::jsonb, 0, 'Above the ramp top the transit times were built on the header trend exactly, so the ratio is 1 and the method returns the hydrostatic there.'),
  ('porepressure', 'intermediate', 'module', 'm01-from-departure-to-pressure', 8, 'Why can the capstone grade the overpressure onset with a tolerance of zero?', '["Because the ramp top was deliberately placed at a round number of metres below the mudline.", "Because onsets are conventionally quoted to the nearest sample and the grid is 10 m.", "Because the graded onset is what a stated rule reports on fixed data, an exactly reproducible fact.", "Because every reasonable method lands within one sample of the mechanism''s true start."]'::jsonb, 2, 'The graded quantity is the output of a stated detection rule on a 10 m grid, not a geological judgement, so there is nothing to be generous about.'),
  ('porepressure', 'intermediate', 'module', 'm01-from-departure-to-pressure', 9, 'Which pressure does the Professional tier add that the Associate tier deliberately did not compute?', '["The hydrostatic pressure of the seawater and pore fluid column.", "The fracture pressure, which stands on the prognosis.", "The overburden stress from the integrated density column.", "The equivalent mud weight of the frame''s two bounding curves."]'::jsonb, 1, 'Fracture pressure stands on a pore pressure estimate through the effective stress, so it could not exist until the prognosis did. EMW was defined at the Associate tier.'),
  ('porepressure', 'intermediate', 'module', 'm01-from-departure-to-pressure', 10, 'At 3000 m the budget is 35.523412418439044 MPa and the encoded overpressure is 2 MPa. What handover fraction must the ratio term supply there?', '["About 5.6 percent.", "About 12.1 percent, the same fraction the method supplies at total depth.", "About 2.0 percent, matching the 2 MPa of overpressure.", "About 9.4 percent, the fraction the method supplies at 3500 m."]'::jsonb, 0, '2 over 35.523412418439044 is 5.63 percent. The fraction grows with depth along the ramp, reaching 9.4 percent at 3500 m and 12.07 at TD.'),
  ('porepressure', 'intermediate', 'module', 'm01-from-departure-to-pressure', 11, 'What does a ratio of exactly 1 make Eaton''s relation return?', '["Zero pressure, since no departure means no signal to convert.", "The overburden, since the whole budget passes to the fluid.", "The fracture pressure, where the walls meet.", "The hydrostatic, exactly, with nothing handed over."]'::jsonb, 3, 'With r = 1 the whole budget stays with the grains: PP = S - (S - Ph) = Ph. The method returns normal pressure without being told to.'),
  ('porepressure', 'intermediate', 'module', 'm01-from-departure-to-pressure', 12, 'Why does this tier work in megapascals rather than mud weight?', '["Because equivalent mud weight cannot represent pressures above the hydrostatic value.", "Because converting to mud units is the Expert tier''s job, and the conversion changes the question being answered.", "Because the mud-weight form requires the water depth, which this tier does not use.", "Because megapascals carry more significant figures than kg/m3 can."]'::jsonb, 1, 'The conversion is information-neutral but question-changing: what-is-the-pressure belongs here, what-mud-balances-it belongs to the tier above.'),
  ('porepressure', 'intermediate', 'module', 'm01-from-departure-to-pressure', 13, 'The Associate tier''s onward lesson already stated the TD overpressure is exactly 6 MPa. What may this tier do with that fact?', '["Present it as this tier''s own discovery, since this is the tier whose machinery computes it.", "Treat it as provisional until the Expert tier''s Bowers cross-check confirms it independently.", "Cite it as known and demonstrate the machinery that recovers it.", "Re-derive it at a different exponent as a check."]'::jsonb, 2, 'Forward-quoted results are cited, never presented as discoveries. The tier''s contribution is running and defending the inversion that reproduces the known answer.'),
  ('porepressure', 'intermediate', 'module', 'm01-from-departure-to-pressure', 14, 'A prognosis reports 20 MPa of overpressure at 2600 m on this well. Why is that impossible to take seriously?', '["The budget there is about 30 MPa, so 20 MPa needs two thirds handed over, requiring a log about 44 percent slow.", "Overpressure on any well is physically capped at the 6 MPa this well reaches at total depth.", "2600 m sits above the ramp top of this well, where overpressure cannot physically exist.", "The capstone''s tolerance on overpressure is 0.01 MPa, which a value of 20 exceeds by three orders."]'::jsonb, 0, 'Two thirds of the budget requires r cubed near 0.33, an enormous slowness the sonic plainly does not show. Budget-and-fraction reasoning kills absurd claims without running anything.'),
  ('porepressure', 'intermediate', 'module', 'm01-from-departure-to-pressure', 15, 'Which statement about the two candidate trends is correct at the start of this tier?', '["The fitted trend is a poor fit, with residuals large enough to disqualify it on statistical grounds alone.", "The two trends agree at depth and disagree only in the first few hundred metres below the mudline.", "The capstone accepts either trend, since each is defensible from the well''s own data.", "The capstone specifies the well''s own header trend; the fitted trend fits its picks perfectly and still misleads."]'::jsonb, 3, 'The fit is exact through its twelve picks, and still the wrong normal for this well; the capstone runs on 656/220/0.0006. Module 4 quantifies the damage.'),
  ('porepressure', 'intermediate', 'module', 'm02-the-eaton-ratio', 1, 'Which way up is the Eaton ratio written?', '["Measured transit time over normal, so overpressure pushes it above 1.", "Normal transit time over measured, so overpressure pulls it below 1.", "Overburden over hydrostatic, so it grows steadily and smoothly with depth.", "Normal transit time over measured, so overpressure pushes it above 1."]'::jsonb, 1, 'The trend goes on top: a slow, undercompacted rock reads a ratio below 1, which the exponent keeps below 1 and the budget converts to a positive handover. Getting it upside down produces pressures below hydrostatic.'),
  ('porepressure', 'intermediate', 'module', 'm02-the-eaton-ratio', 2, 'What is the Eaton ratio at total depth on the well''s own trend?', '["0.9955420863389854.", "0.9808693876607879.", "0.9580337483265022.", "0.8793108342707514."]'::jsonb, 2, '259.5530276341839 over 270.92263512383806. The 0.9955 and 0.9809 values belong to 2600 m and 3000 m, and 0.8793 is the TD ratio already cubed.'),
  ('porepressure', 'intermediate', 'module', 'm02-the-eaton-ratio', 3, 'How large is the worst slowness anywhere in this well, relative to trend?', '["About 4 percent, at total depth.", "About 12 percent, at total depth.", "About 44 percent, at the ramp top.", "About 1 percent, at 3000 m."]'::jsonb, 0, 'The TD ratio 0.958 means the rock is about 4 percent slow. That 4 percent carries the whole 6 MPa; Eaton signals live very close to 1.'),
  ('porepressure', 'intermediate', 'module', 'm02-the-eaton-ratio', 4, 'Why is the locality of the ratio, each sample judged alone, both a strength and a hazard?', '["Strength: errors at neighbouring samples average out over the curve. Hazard: the averaging conceals genuine one-sample spikes entirely.", "Strength: noise spikes visibly rather than smearing. Hazard: no context, so any slow interval becomes pressure.", "Strength: the ratio needs no trend. Hazard: it needs the exponent instead.", "Strength: bad samples propagate to neighbours for review. Hazard: review is slow."]'::jsonb, 1, 'A noisy sample contaminates one depth, visibly. But the ratio cannot tell undercompaction from washout, lithology or gas, so screening upstream is mandatory.'),
  ('porepressure', 'intermediate', 'module', 'm02-the-eaton-ratio', 5, 'Using the small-departure rule, a ratio 0.5 percent below 1 at n = 3 hands the fluid roughly what share of the budget?', '["About 0.5 percent.", "About 3 percent.", "About 1.5 percent.", "About 4.5 percent."]'::jsonb, 2, 'For small x, (1-x)^3 is about 1-3x, so the handover is about three times the fractional slowness: 1.5 percent.'),
  ('porepressure', 'intermediate', 'module', 'm02-the-eaton-ratio', 6, 'What is the overpressure formula in budget-and-fraction form?', '["OP = (S - Ph)(1 - r^n).", "OP = S(1 - r^n) - Ph.", "OP = (S + Ph)(1 - r)^n.", "OP = (S - Ph) r^n, the grains'' retained share."]'::jsonb, 0, 'Overpressure is the budget times the handover fraction. The last option is the effective stress kept by the grains, not the part handed over.'),
  ('porepressure', 'intermediate', 'module', 'm02-the-eaton-ratio', 7, 'Between 2600 m and TD, the handover fraction rises from 1.33 to 12.07 percent while the encoded overpressure rises 0.4 to 6 MPa. Why do the two columns grow at different rates?', '["Floating point loses precision at depth, separating the columns.", "The exponent grows with depth, amplifying the deep fractions.", "The budget also grows with depth, so a given pressure needs a smaller share of it.", "The trend flattens toward the matrix time at depth, capping the fraction the ratio can reach."]'::jsonb, 2, 'Overpressure is fraction times budget. With the budget growing 30.04 to 49.71 MPa, the fraction must grow slower than the pressure it produces.'),
  ('porepressure', 'intermediate', 'module', 'm02-the-eaton-ratio', 8, 'Which log error enters the pressure through the budget rather than through the fraction?', '["A miscalibrated sonic tool reading 2 percent slow everywhere.", "A density log biased 2 percent light.", "A trend fitted 2 percent low.", "Shale picks taken in a silty interval."]'::jsonb, 1, 'The budget is S minus Ph, built from the density column. Sonic, trend and pick errors all enter through the ratio side; the two error families multiply.'),
  ('porepressure', 'intermediate', 'module', 'm02-the-eaton-ratio', 9, 'What does n = 1 do on this well at TD?', '["Returns the hydrostatic everywhere, since the amplification has been switched off entirely.", "Leaves 2.0863306869306193 MPa of overpressure from the raw ratio.", "Halves the capstone answer to exactly 3 MPa.", "Returns the full 6 MPa, since the encoding does not depend on n."]'::jsonb, 1, 'n = 1 still reads the raw ratio: about a third of the n = 3 answer survives. Only a ratio of 1 silences the method; the exponent merely rescales.'),
  ('porepressure', 'intermediate', 'module', 'm02-the-eaton-ratio', 10, 'Which overpressure mechanism does Eaton''s sonic form systematically under-read?', '["Disequilibrium compaction in a rapidly loaded basin, where burial outruns dewatering.", "A pressure ramp encoded into transit times.", "Undercompaction beneath a thick shale seal.", "Late fluid expansion in rock that has already compacted."]'::jsonb, 3, 'Post-compaction mechanisms leave little porosity signature, so the ratio sits near 1 while true pressure is high. The other three are exactly the signature the method reads.'),
  ('porepressure', 'intermediate', 'module', 'm02-the-eaton-ratio', 11, 'A washed-out interval at 3000 m slows the log to 320 us/m against a trend of 292.07. What does the machinery report there, against a true 2 MPa?', '["About 8.5 MPa of overpressure.", "About 2.4 MPa, a mild overstatement.", "Nothing, since washouts are automatically excluded.", "A negative overpressure, flagging the bad hole."]'::jsonb, 0, 'The ratio 0.9127 cubes to 0.760, and 24 percent of the 35.52 MPa budget is 8.51 MPa. The engine computes wherever it is pointed; the caliper screen is the defence.'),
  ('porepressure', 'intermediate', 'module', 'm02-the-eaton-ratio', 12, 'What does a ratio above 1 produce, and what does it usually mean?', '["Zero pressure, since the method clips its output at the hydrostatic; it means the trend is locally exact.", "Pressure below hydrostatic; usually a cemented streak or a trend fitted too high, not real subpressure.", "The overburden, since fast rock carries the whole load; it means the seal is leaking.", "An engine error, since the power law rejects ratios above 1; it means a data gap."]'::jsonb, 1, 'Eaton extrapolates symmetrically into the fast side with no opinion. Subhydrostatic output in undrilled shale is a trend alarm before it is a prediction.'),
  ('porepressure', 'intermediate', 'module', 'm02-the-eaton-ratio', 13, 'Why does the direction of a trend error matter as much as its size?', '["A low trend invents pressure loudly; a high trend hides it quietly, and quiet errors drill underbalanced.", "Only low trends propagate through the exponent''s cube; high-side errors cancel inside the ratio before amplification.", "High trends fail the fit statistics, so they are caught at fitting time.", "The direction sets which unit system the error appears in."]'::jsonb, 0, 'Over-reading triggers scrutiny; under-reading drills underbalanced. The dangerous direction is the quiet one.'),
  ('porepressure', 'intermediate', 'module', 'm02-the-eaton-ratio', 14, 'In the worked chain at 3000 m, which two intermediates must be carried at full precision to land inside the 0.01 MPa tolerance?', '["The water depth and the seawater density.", "The sample interval and the ramp rate.", "The trend exponential and the cubed ratio.", "The overburden and the graded tolerance itself."]'::jsonb, 2, 'Rounding e to the minus 1.8 or the cube mid-chain drifts the final digits. Carry them fully, round only the reported value.'),
  ('porepressure', 'intermediate', 'module', 'm02-the-eaton-ratio', 15, 'The five-step chain at 3500 m uses log 282.5387777324301 us/m and budget 42.544004457243325 MPa. What overpressure results?', '["2.0 MPa, matching the graded mid-ramp value.", "4.0 MPa.", "6.0 MPa, since the chain always lands on the TD answer.", "3.8 MPa, short of the ramp because of trapezoidal error."]'::jsonb, 1, 'The ratio 0.9676229398047687 cubes to 0.9059797014636933; 9.4 percent of the budget is exactly 4 MPa, the ramp 1000 m below its top.'),
  ('porepressure', 'intermediate', 'module', 'm03-the-prognosis-down-the-well', 1, 'On capstone settings, what does the pore pressure curve do between the mudline and 2500 m?', '["Wanders slightly around the hydrostatic, as real prognoses do.", "Lies exactly on the hydrostatic, to floating-point residue.", "Tracks the fracture pressure at a fixed offset below it.", "Rises at 4 kPa per metre above the hydrostatic from the seabed down."]'::jsonb, 1, 'Every sample above the ramp top has a ratio of exactly 1 by construction, so the method returns the hydrostatic to the last bit. The wander is the real-well signature, absent here.'),
  ('porepressure', 'intermediate', 'module', 'm03-the-prognosis-down-the-well', 2, 'What is the slope of the pore pressure curve below the onset, and how does it decompose?', '["14.1 kPa per metre: 10.1 of hydrostatic gradient plus the 4 of encoded ramp.", "10.1 kPa per metre: the pore fluid density times gravity, unchanged by the ramp.", "4 kPa per metre: the ramp alone, since the hydrostatic is a constant.", "24.6 kPa per metre: the local overburden gradient at total depth."]'::jsonb, 0, 'The prognosis slope is hydrostatic-plus-mechanism. Reading slopes in kPa per metre is how artefacts with impossible gradients are spotted at a glance.'),
  ('porepressure', 'intermediate', 'module', 'm03-the-prognosis-down-the-well', 3, 'The detection rule reports the onset at 2520 m. What is the overpressure at 2510 m?', '["Exactly zero, because the ramp only starts below 2510 m.", "0.08 MPa, which clears the threshold.", "0.04 MPa: real, but under the 0.05 MPa threshold.", "0.05 MPa exactly, which the strict inequality rejects."]'::jsonb, 2, 'The ramp adds 0.04 MPa per sample. At 2510 the anomaly is real but under threshold; at 2520 it reads 0.08 and the flag fires.'),
  ('porepressure', 'intermediate', 'module', 'm03-the-prognosis-down-the-well', 4, 'Which set of choices does a reported onset depend on, besides the geology?', '["The water depth, the datum and the mud weight in the hole.", "The detection threshold, the sample grid and the exponent.", "The matrix transit time and the seawater density.", "The tolerance fields of the capstone form."]'::jsonb, 1, 'The threshold sets what counts as flagged, the grid quantises the answer, and the exponent scales how fast the anomaly clears the bar: 2540 m at n 1, 2510 at n 4, same well.'),
  ('porepressure', 'intermediate', 'module', 'm03-the-prognosis-down-the-well', 5, 'What does the closed loop on this well actually prove?', '["That Eaton''s power law describes shale compaction correctly in every basin the method is used in.", "That n = 3 is the correct exponent for most basins.", "That a single trend suffices for real prognosis work.", "That the pipeline is implemented correctly, end to end."]'::jsonb, 3, 'The well was built from the equation, so recovery certifies arithmetic, not geology. Real-world validity still comes from measured pressures.'),
  ('porepressure', 'intermediate', 'module', 'm03-the-prognosis-down-the-well', 6, 'How large is the worst gap between recovered overpressure and the encoded ramp, on capstone settings?', '["About 2.2e-8 Pa, across all 401 samples.", "About 0.01 MPa, the capstone tolerance.", "About 0.4 MPa, at the first ramp sample.", "Exactly zero at every sample, as integers."]'::jsonb, 0, 'Fifteen significant figures of agreement: floating-point residue, not approximation. The loop tile reports this number live.'),
  ('porepressure', 'intermediate', 'module', 'm03-the-prognosis-down-the-well', 7, 'At n = 4 on the well trend, where does the worst ramp disagreement sit and how big is it?', '["At the onset, 0.05 MPa, where detection just fires.", "At 3640 m, 6.497 MPa, where the proportional trend error and the growing budget trade off.", "At total depth, 1.8345331768896282 MPa.", "Above the ramp top, where any exponent error is amplified most."]'::jsonb, 2, 'Exponent error compounds with anomaly size, so the miss peaks at TD. The 3640 m figure belongs to the fitted-trend experiment, a different error.'),
  ('porepressure', 'intermediate', 'module', 'm03-the-prognosis-down-the-well', 8, 'A vendor reproduces this golden well to machine precision and offers that as proof their software predicts pressure correctly in your basin. What is the right response?', '["Accept it: recovery of a forward-inverse-consistent fixture at machine precision is the strongest validation software can offer.", "Reject the software: synthetic tests prove nothing about implementations.", "Ask for the same test at n = 1.2 before accepting the claim.", "Accept it as proof of implementation only; basin validity still needs local calibration."]'::jsonb, 3, 'The loop certifies arithmetic. The risky parts, trend, exponent, mechanism, are exactly what a fixture built from the equation cannot test.'),
  ('porepressure', 'intermediate', 'module', 'm03-the-prognosis-down-the-well', 9, 'Which four pressures must appear in fixed order at every depth of a healthy prognosis?', '["Hydrostatic, pore pressure, fracture pressure, overburden.", "Pore pressure, hydrostatic, overburden, fracture pressure.", "Hydrostatic, fracture pressure, pore pressure, overburden.", "Overburden, fracture pressure, pore pressure, hydrostatic."]'::jsonb, 0, 'Reading upward in pressure at TD: 41.409, 47.409, 76.552, 91.123 MPa. Any violated ordering means something upstream is broken.'),
  ('porepressure', 'intermediate', 'module', 'm03-the-prognosis-down-the-well', 10, 'The graded trend value at TD is 259.5530276341839 us/m. What is the most common slip on this field?', '["Evaluating e to the minus 2.4 with too few digits and drifting outside the 0.5 us/m tolerance.", "Quoting the log''s 270.92263512383806 us/m instead.", "Evaluating the trend at 3900 m instead of 4000.", "Adding the matrix time twice in the exponential form."]'::jsonb, 1, 'The log and trend values sit side by side in the working. Their 11.37 us/m difference is the entire evidence of the prognosis, which makes the swap easy and costly.'),
  ('porepressure', 'intermediate', 'module', 'm03-the-prognosis-down-the-well', 11, 'Why do the capstone''s pp_td and op_td fields check each other?', '["Both carry the same 0.01 MPa tolerance, so passing one field mathematically guarantees passing the other.", "They differ by exactly the hydrostatic at TD.", "They are graded from separate engines, so agreement is evidence.", "The exam rejects submissions where they differ at all."]'::jsonb, 1, '47.408579625 minus 6 is 41.408579625. Internal consistency is free error detection: compute two, check the third.'),
  ('porepressure', 'intermediate', 'module', 'm03-the-prognosis-down-the-well', 12, 'Both the log and the trend DECREASE with depth even as overpressure grows. Why does this not contradict undercompaction?', '["It genuinely contradicts it, and the inconsistency is a deliberate flaw planted for this module to find.", "The decrease is a display convention of transit-time plots.", "Compaction continues below the onset, at a deficit; overpressure is a widening gap between falling curves.", "The density log compensates, so the product of the two is constant."]'::jsonb, 2, 'The overpressured shale at 4000 m compacted less than a normal 4000 m shale, but more than the 3000 m shale. A sonic that actually reverses is a far bigger anomaly than this well contains.'),
  ('porepressure', 'intermediate', 'module', 'm03-the-prognosis-down-the-well', 13, 'What is the honest way to estimate pore pressure at 3250 m from quoted values at 3000 and 3500 m?', '["Interpolate the two quoted pore pressures linearly and take the midpoint of the interval as the answer.", "Interpolate the overpressures, then add the hydrostatic computed properly at 3250 m.", "Average the two ratios and rerun the exponent on the mean.", "Read the fracture pressure at 3250 m and subtract the window."]'::jsonb, 1, 'Interpolate residuals, not totals: overpressure is the small smooth part. Direct pressure interpolation happens to work on this well only because both parts are linear.'),
  ('porepressure', 'intermediate', 'module', 'm03-the-prognosis-down-the-well', 14, 'Under a 0.1 MPa threshold, what onset would the rule report on capstone settings?', '["2510 m.", "2520 m.", "2530 m.", "2550 m."]'::jsonb, 2, 'The sequence runs 0.04, 0.08, 0.12 MPa at 2510, 2520, 2530: the first value strictly above 0.1 sits at 2530 m.'),
  ('porepressure', 'intermediate', 'module', 'm03-the-prognosis-down-the-well', 15, 'Why does the reported onset at the 0.2 MPa threshold, 2550 m, sit on a floating-point hair?', '["The 2550 m sample computes to 0.20000000000000745 MPa, a residue over the strict threshold; exact decimals would report 2560.", "The 10 m grid cannot represent 2550 m exactly in binary.", "The threshold 0.2 is not representable, so the engine rounds it to 0.19.", "The comparison uses greater-or-equal, which ties at exactly 0.2."]'::jsonb, 0, 'The engine''s sum lands a hair over 0.2 and the strict comparison fires. The lesson: never set a threshold exactly on a value the data can take.'),
  ('porepressure', 'intermediate', 'module', 'm04-the-trend-lever', 1, 'Run the capstone prognosis on the fitted trend instead of the well''s own. What is the overpressure at TD?', '["12.429177480013587 MPa, more than double the true 6.", "6.429177480013587 MPa, the true value plus the trend gap.", "8.25 MPa, the same error factor as at 3000 m.", "5.696540131931327 MPa, slightly under the true value."]'::jsonb, 0, 'The fitted trend more than doubles the answer. The 6.43 figure is the ERROR, not the total; 8.25 is the phantom overpressure at 3000 m; 5.697 is the phantom just above the ramp top.'),
  ('porepressure', 'intermediate', 'module', 'm04-the-trend-lever', 2, 'Where does the fitted-trend prognosis report the overpressure onset?', '["2520 m, unchanged, since onsets do not depend on the trend.", "2400 m, one casing seat shallow of the truth.", "120 m below the mudline.", "At the mudline itself, since the trends differ there by 6 us/m."]'::jsonb, 2, 'The fitted trend sits low from near the surface, so phantom pressure clears the 0.05 MPa threshold by the twelfth sample. The absurd onset is the diagnostic gift.'),
  ('porepressure', 'intermediate', 'module', 'm04-the-trend-lever', 3, 'Why is the shallow section the place where a low trend is easiest to convict?', '["Because the stress budget is at its largest in the shallow section, making any error loudest there.", "Because everything shown there should be absent: where truth is zero, all signal is artefact.", "Because shallow samples are logged twice on most wells.", "Because the exponent is not applied above the onset."]'::jsonb, 1, 'Deep in the ramp, error and signal mix. In known-normal section, any reported overpressure is pure artefact, legible at a glance.'),
  ('porepressure', 'intermediate', 'module', 'm04-the-trend-lever', 4, 'What is the three-stage estimate for the phantom overpressure a trend error produces?', '["Delta OP is about epsilon times (S - Ph) over n.", "Delta OP is about n times epsilon times (S - Ph).", "Delta OP is about n times epsilon times the measured pressure.", "Delta OP is about epsilon cubed times the budget."]'::jsonb, 1, 'One-for-one into the ratio, times n through the power law, times the budget into megapascals. It runs about ten percent hot from linearising the cube.'),
  ('porepressure', 'intermediate', 'module', 'm04-the-trend-lever', 5, 'The trend gap between header and fitted peaks at 26.84 us/m. At what depth?', '["At the mudline, where the mudline values differ.", "At total depth, where the two decay constants have been acting on the exponential for the longest run.", "At the ramp top, where the encoding begins.", "At 1400 m, before both curves converge on the matrix time."]'::jsonb, 3, 'Both trends decay toward 220 us/m, so the absolute gap grows, peaks mid-well, and narrows again; the PROPORTIONAL gap keeps growing with depth.'),
  ('porepressure', 'intermediate', 'module', 'm04-the-trend-lever', 6, 'For a pressure good to 1 MPa at TD via Eaton at n 3, how accurate must the trend be there?', '["About 1.7 us/m, two thirds of one percent of the trend value.", "About 13.4 us/m, the gap between this well''s two candidate trends.", "About 0.5 us/m, the capstone''s tolerance on the trend field.", "About 6 us/m, the mudline disagreement."]'::jsonb, 0, 'Inverting the three-stage estimate: epsilon = 1 over (3 times 49.7) = 0.0067. This well''s actual trend disagreement is eight times that, which is why the trend dominates the error budget.'),
  ('porepressure', 'intermediate', 'module', 'm04-the-trend-lever', 7, 'A mudline-only shift of 10 us/m in the trend costs about 0.52 MPa at TD. Why so little, when the fitted trend''s error cost 6.4?', '["Mudline shifts are corrected automatically by the least-squares fitting routine before the prognosis runs.", "A mudline shift decays away with the exponential; the fitted trend''s error lives in the decay constant instead.", "The 10 us/m shift is smaller than the 6 us/m trend gap.", "Mudline shifts move the hydrostatic, not the ratio."]'::jsonb, 1, 'At TD the shifted mudline contributes 10 times e to the minus 2.4, under 1 us/m. WHERE a trend error lives matters more than its surface size.'),
  ('porepressure', 'intermediate', 'module', 'm04-the-trend-lever', 8, 'Which checklist item would have caught the fitted trend BEFORE any prognosis was run?', '["Parameter physicality: mudline values of 650 and decay constants of 0.7 per km are outside the plausible ranges for marine shale.", "The leak-off test at the deepest casing shoe.", "Pick interrogation: do the picks describe the population the trend will judge?", "The exponent sensitivity table."]'::jsonb, 2, '650 and 0.7 are individually physical, so parameter checks pass. The defect was in the picks, whose fit statistics were perfect while their population misled.'),
  ('porepressure', 'intermediate', 'module', 'm04-the-trend-lever', 9, 'What does check one of the trend defence require?', '["The prognosis returns near-hydrostatic pressure wherever the well is known normal.", "The fit residuals through the shale picks are each below one microsecond per metre.", "The trend parameters match the regional average within ten percent.", "The onset lands within two samples of the ramp top."]'::jsonb, 0, 'Drilling history is pressure data of a rough kind: hole that drilled quiet with light mud convicts any trend that claims it was overpressured.'),
  ('porepressure', 'intermediate', 'module', 'm04-the-trend-lever', 10, 'The fitted-trend curve is perfectly smooth and internally consistent. What does that teach about trend errors?', '["Smoothness certifies the trend, since artefacts are always spiky.", "Internal consistency of the curve implies the pressures are at worst a few tenths of a megapascal wrong.", "They are caught at the output by inspecting curve texture.", "They are systematic and invisible in the product, so they must be caught at the input."]'::jsonb, 3, 'Bias produces beautiful curves; noise produces ugly ones. The dangerous errors are the beautiful kind, and only input-side defence catches them.'),
  ('porepressure', 'intermediate', 'module', 'm04-the-trend-lever', 11, 'What is the honest way to present pressure results when two candidate trends cannot be discriminated yet?', '["Present the arithmetic average of the two prognoses as the single base case the plan is built on.", "Report the spread, 47.41 to 53.84 MPa at TD, as the trend uncertainty, with a named discriminator.", "Present the higher curve only, as the conservative choice for every purpose.", "Withhold pressures entirely until a measurement exists."]'::jsonb, 1, 'An average describes neither candidate; a single curve hides a known uncertainty. The band, plus a named discriminator, is the professional form.'),
  ('porepressure', 'intermediate', 'module', 'm04-the-trend-lever', 12, 'The fitted-trend run''s worst ramp disagreement is 6.497 MPa. Where does it sit, and why not at TD?', '["At the onset, because that is where the detection rule''s error contribution dominates the total.", "At 2500 m exactly, where the phantom is purest.", "At 3640 m, where the falling trend error and the rising budget trade off.", "At TD, because trend errors always compound downward."]'::jsonb, 2, 'Phantom pressure is roughly n times epsilon(z) times budget(z): epsilon falls with depth while the budget rises, and their product peaks inside the ramp, not at its bottom.'),
  ('porepressure', 'intermediate', 'module', 'm04-the-trend-lever', 13, 'Just above the ramp top, where true overpressure is zero, the fitted trend reports how much?', '["About 5.7 MPa.", "About 0.05 MPa, exactly at threshold.", "About 1.6 MPa, as at 1000 m.", "About 12.4 MPa, the TD phantom."]'::jsonb, 0, '5.696540131931327 MPa at 2500 m: nearly the whole true TD anomaly, invented where there is nothing to invent. Errors concentrate where signal should be absent.'),
  ('porepressure', 'intermediate', 'module', 'm04-the-trend-lever', 14, 'Which single question, put to a report that quoted only the deep section, exposed the fitted trend?', '["What is the fracture pressure at total depth?", "What is the pressure at 1000 m?", "Which exponent was used below the onset?", "What tolerance did the capstone allow?"]'::jsonb, 1, 'The answer, hydrostatic plus 1.59 MPa in section that drilled quiet on 1030 mud, is impossible. Reports that show only the interesting section hide the section that would convict them.'),
  ('porepressure', 'intermediate', 'module', 'm04-the-trend-lever', 15, 'A trend error of the OPPOSITE sign, fitted high rather than low, would differ how?', '["It would be caught by the same spurious-onset signature, since trend errors of either sign invent shallow pressure.", "It would suppress real overpressure and read subhydrostatic shale: quieter, and more dangerous.", "It would double pressures like the low trend, since errors enter through a square.", "It would cancel against the exponent, leaving pressures unchanged."]'::jsonb, 1, 'A high trend hides pressure instead of inventing it. Its visible symptom, pressures below hydrostatic in undrilled shale, is subtler, and the failure mode is mud that is too light.'),
  ('porepressure', 'intermediate', 'module', 'm05-fracture-pressure', 1, 'What is the coefficient form of fracture pressure?', '["FP = K(S - PP) + PP.", "FP = K(S - Ph) + Ph.", "FP = S - K(S - PP).", "FP = (S + PP) / K."]'::jsonb, 0, 'Keep the fraction K of the effective stress as horizontal confinement, add back the pore pressure. The second option mixes with the hydrostatic, a classic slip worth 2 MPa at TD.'),
  ('porepressure', 'intermediate', 'module', 'm05-fracture-pressure', 2, 'With Poisson''s ratio 0.4, what is K?', '["0.4, the ratio used directly.", "Two thirds, from nu over one minus nu.", "0.6, from one minus nu.", "1.5, the reciprocal of two thirds."]'::jsonb, 1, 'K = 0.4 / 0.6 = 2/3 exactly. Using nu directly as K gives 64.894 MPa at TD instead of 76.552, an 11.7 MPa miss.'),
  ('porepressure', 'intermediate', 'module', 'm05-fracture-pressure', 3, 'Read as a mixture, where does the fracture pressure sit?', '["A weighted average of hydrostatic and overburden, weighted one third and two thirds respectively at every depth.", "Halfway between pore pressure and overburden at every depth.", "Two parts overburden, one part pore pressure: a weighted average of those two.", "At the pore pressure plus a fixed 29 MPa offset."]'::jsonb, 2, 'FP = KS + (1-K)PP. The mixture reading explains the orderings: a weighted average cannot leave the interval between its ingredients.'),
  ('porepressure', 'intermediate', 'module', 'm05-fracture-pressure', 4, 'How much of a pore pressure change passes through to the fracture pressure?', '["One third of it.", "Two thirds of it.", "All of it, one for one.", "None: the ceiling depends only on the overburden."]'::jsonb, 0, 'dFP/dPP = 1 - K = 1/3. The fitted-trend experiment measured exactly this: 2.143 MPa of ceiling rise for 6.429 of floor rise.'),
  ('porepressure', 'intermediate', 'module', 'm05-fracture-pressure', 5, 'How does one megapascal of overpressure change the pressure-unit window FP minus PP?', '["Widens it by one third of a megapascal.", "Narrows it by two thirds of a megapascal.", "Leaves it unchanged, since both walls rise together.", "Narrows it by exactly one megapascal."]'::jsonb, 1, 'The window is K(S - PP), so its derivative in PP is minus K. Floor up 1, ceiling up a third, gap down two thirds: the mechanical reason overpressured wells are hard.'),
  ('porepressure', 'intermediate', 'module', 'm05-fracture-pressure', 6, 'At TD the fracture pressure is 76.55157117548856 MPa. Verify it from the mixture in one line.', '["Two thirds of 91.12306695073282 plus one third of 47.408579625.", "Two thirds of 91.12306695073282 plus one third of 41.408579625.", "One third of 91.12306695073282 plus two thirds of 47.408579625.", "Two thirds of the budget 49.714487325732826 plus the hydrostatic."]'::jsonb, 0, '60.749 plus 15.803 gives 76.552. Option two mixes with the hydrostatic and gives 74.552; option four is the no-ramp counterfactual ceiling.'),
  ('porepressure', 'intermediate', 'module', 'm05-fracture-pressure', 7, 'In the normal section, what is the fracture pressure curve made of?', '["New information extracted from the sonic log''s departure, scaled by the coefficient K.", "The frame re-weighted: two thirds overburden, one third hydrostatic.", "The pore pressure curve at a fixed offset of K MPa.", "The leak-off tests interpolated between casing shoes."]'::jsonb, 1, 'Above the onset PP equals Ph, so the ceiling inherits everything from the frame. Fracture-gradient uncertainty there IS overburden uncertainty.'),
  ('porepressure', 'intermediate', 'module', 'm05-fracture-pressure', 8, 'What did the overpressure ramp cost this well in window terms at TD?', '["Exactly 6 MPa, the full overpressure.", "Exactly 2 MPa, one third of it.", "Nothing: the ceiling rose to compensate.", "Exactly 4 MPa, two thirds of the 6 MPa."]'::jsonb, 3, 'The window would be 33.14 MPa with no ramp, two thirds of the budget; with 6 MPa handed over it is 29.14. The loss is K times the overpressure.'),
  ('porepressure', 'intermediate', 'module', 'm05-fracture-pressure', 9, 'What does a leak-off test actually measure?', '["The overburden stress at the casing shoe, read directly from the pressure-volume line''s slope.", "The pore pressure of the sand nearest the shoe.", "Fracture initiation at the shoe: one measured point of the ceiling curve.", "The equivalent circulating density limit of the mud pumps."]'::jsonb, 2, 'Pressure the shoe slowly until the pressure-volume line breaks: fracture initiation, one honest point per casing string, from which K is back-calculated.'),
  ('porepressure', 'intermediate', 'module', 'm05-fracture-pressure', 10, 'A leak-off at 3000 m measures 55.0 MPa against the prognosis PP of 33.307730125 and S of 66.83114254343904. What K does it imply?', '["0.6667, confirming the elastic value.", "0.6471.", "0.8231, indicating tectonic compression.", "0.5000, indicating a weak shale."]'::jsonb, 1, 'K = (55.0 - 33.307730125)/(66.83114254343904 - 33.307730125) = 0.6471, slightly below the elastic 2/3, and carried downward in its place.'),
  ('porepressure', 'intermediate', 'module', 'm05-fracture-pressure', 11, 'Why does calibrated practice use K(z) as a depth function rather than one number?', '["Because tests at different shoes back-calculate different K values, a twist no single K removes.", "Because the engine requires a K per sample to run.", "Because Poisson''s ratio is exactly 0.4 at one depth only, and drifts with compaction above and below it.", "Because regulations require a fresh K per casing string."]'::jsonb, 0, 'Field data commonly shows K rising with depth. A fixed K is then high at shallow shoes and low at deep ones, an error shaped like a twist, not an offset.'),
  ('porepressure', 'intermediate', 'module', 'm05-fracture-pressure', 12, 'Which physics does the coefficient form NOT contain?', '["The dependence of fracture pressure on pore pressure.", "The proportional response of horizontal stress to vertical effective load.", "Tectonic stress, anisotropy, hole inclination and tensile strength.", "The ordering of the four pressures at a depth."]'::jsonb, 2, 'The form is vertical-loading elasticity only; everything else is smeared into the calibrated K by leak-off tests. Knowing what K hides is the difference between using and believing.'),
  ('porepressure', 'intermediate', 'module', 'm05-fracture-pressure', 13, 'Five points of K uncertainty is worth how much fracture pressure at this well''s TD?', '["About 0.5 MPa, comfortably inside the capstone''s stated tolerance for the field.", "About 2.19 MPa: the effective stress times 0.05.", "About 6.43 MPa, matching the trend''s damage.", "About 11.7 MPa, the cost of using nu directly."]'::jsonb, 1, 'dFP/dK = S - PP = 43.714 MPa, so 0.05 of K moves the ceiling 2.186 MPa. Comparable to the trend''s ceiling effect, but affecting only the ceiling.'),
  ('porepressure', 'intermediate', 'module', 'm05-fracture-pressure', 14, 'Why do K errors deserve less alarm than trend errors of similar size?', '["Because K errors are always positive in compacting basins while trend errors alternate in sign per well.", "Because the ceiling has no operational role once drilling starts.", "Because leak-off tests are cheap while measured pressures are not.", "K passes through linearly, once: no exponent amplifies it, and it never touches the floor."]'::jsonb, 3, 'The trend error runs through the cube and the budget and moves the kick-side wall. K''s error is linear, ceiling-only, and calibrated per shoe.'),
  ('porepressure', 'intermediate', 'module', 'm05-fracture-pressure', 15, 'Can the coefficient form yield a fracture pressure above the overburden?', '["Never, under any parameterisation of K.", "Not from elasticity, where nu below 0.5 keeps K below 1; but a calibrated K above 1 can, under tectonic compression.", "Yes, whenever the pore pressure exceeds the hydrostatic.", "Only if the Poisson''s ratio is entered as a percentage."]'::jsonb, 1, 'The weighted-average guarantee holds only for K between 0 and 1. Strong horizontal compression genuinely puts fracture pressure above vertical stress, and the calibrated K carries it.'),
  ('porepressure', 'intermediate', 'module', 'm06-the-prognosis-workflow', 1, 'Why must the frame be fixed and checked before the trend is chosen?', '["Because the exact least-squares fitting routine consumes the trapezoidal overburden as one of its inputs.", "Because the quiet-section defence needs the hydrostatic to compare against.", "Because the frame depends on the exponent chosen later.", "Because migration software loads them in that order."]'::jsonb, 1, 'Each workflow step consumes the previous one''s output: the quietness check judges the prognosis against the hydrostatic, which must already be trusted.'),
  ('porepressure', 'intermediate', 'module', 'm06-the-prognosis-workflow', 2, 'What belongs in the screening step''s output, even on this synthetic well where nothing is removed?', '["An explicit statement that all 401 samples were screened and pass.", "Nothing: an empty screen needs no record.", "The caliper log itself, attached in full.", "A revised trend refitted to only those samples that survived the caliper and lithology screens."]'::jsonb, 0, 'A prognosis that does not name its screening is not reproducible. Stating that nothing was removed is itself information.'),
  ('porepressure', 'intermediate', 'module', 'm06-the-prognosis-workflow', 3, 'Which check runs LAST in the workflow, and why?', '["The frame check, since it is cheapest.", "The onset detection, since it cannot run until the full pressure curve exists at every sample.", "The closure against whatever ground truth exists, since it tests everything at once.", "The fracture pressure, since the ceiling is optional."]'::jsonb, 2, 'The closure step is last and strongest: on this well the encoded ramp, on a real well measured pressures and drilling events. A prognosis with no closure attempt is a hypothesis in a suit.'),
  ('porepressure', 'intermediate', 'module', 'm06-the-prognosis-workflow', 4, 'In the QC list, what failure does the slope check catch?', '["Unit slips in the density integration that shift the overburden by a constant factor everywhere.", "Trend bias in the shallow section.", "Transcription errors between tables and text.", "Artefacts at trend joins and splices with physically impossible gradients."]'::jsonb, 3, 'A pore pressure slope steeper than the local overburden gradient, about 24.6 kPa per metre at TD here, cannot be sustained along a ramp; such features are artefacts.'),
  ('porepressure', 'intermediate', 'module', 'm06-the-prognosis-workflow', 5, 'The QC list is explicitly unable to catch one class of error. Which?', '["Shared error: a biased input moving every internally consistent curve together.", "Spiky noise in a single sonic sample.", "An inverted Eaton ratio, with the measured transit time mistakenly placed over the trend value.", "A fracture pressure above the overburden."]'::jsonb, 0, 'QC catches inconsistency. A biased density log biases overburden, budget, pressures and ceiling coherently, passing every internal check; only external measurement catches it.'),
  ('porepressure', 'intermediate', 'module', 'm06-the-prognosis-workflow', 6, 'A loop residual that is uniform in depth, neither growing with budget nor with anomaly, points at which input?', '["The exponent, misapplied below the onset.", "The hydrostatic reference''s datum, such as a wrong water depth.", "The compaction trend''s decay constant, biased by shale picks concentrated in the shallow section.", "The cube step, applied twice."]'::jsonb, 1, 'A datum slip shifts the hydrostatic by a constant column everywhere; trend and exponent errors scale with depth or anomaly. Residual structure is a map of where to look.'),
  ('porepressure', 'intermediate', 'module', 'm06-the-prognosis-workflow', 7, 'Which capstone field is graded with tolerance zero?', '["The NCT transit time at TD.", "The pore pressure at 3000 m.", "The overpressure onset depth.", "The fracture pressure at TD."]'::jsonb, 2, 'The onset is the output of a stated rule on fixed data: 2520 m, exactly reproducible. The pressures carry 0.01 MPa and the trend 0.5 us/m.'),
  ('porepressure', 'intermediate', 'module', 'm06-the-prognosis-workflow', 8, 'Which pair of graded values are exact by construction rather than computed chains?', '["The onset, by the rule, and the overpressure at TD, by the ramp.", "The two pore pressures, by the encoding.", "The trend evaluation at TD together with the coefficient-form fracture pressure built upon it.", "The onset and the NCT at TD."]'::jsonb, 0, '2520 follows from the detection rule; 6 MPa is 4 kPa per metre over 1500 m. The pore pressures are five-step chains; trend and FP are single evaluations.'),
  ('porepressure', 'intermediate', 'module', 'm06-the-prognosis-workflow', 9, 'The most common slip on the fracture pressure field is using nu directly as K. What does it produce at TD?', '["76.552 MPa, by luck of cancellation.", "64.894 MPa, wrong by 11.7.", "74.552 MPa, the hydrostatic-mixture value.", "91.123 MPa, the overburden."]'::jsonb, 1, '0.4 times 43.714 plus 47.409 is 64.894. The other named slip, mixing with the hydrostatic, gives 74.552; the mixture identity catches both.'),
  ('porepressure', 'intermediate', 'module', 'm06-the-prognosis-workflow', 10, 'Why does the capstone report of this course fit in four lines?', '["Because the grading form truncates longer submissions.", "Because pressures above the detected onset are conventionally omitted from summary reporting.", "Because tolerances make detail pointless.", "Because a defended prognosis compresses to frame, trend, prognosis and ceiling, one line each."]'::jsonb, 3, 'Frame, trend, prognosis, ceiling: one line each, every number defensible, every choice named. Compression is a property of finished work.'),
  ('porepressure', 'intermediate', 'module', 'm06-the-prognosis-workflow', 11, 'In the wrong-run summary, which line fails review on its face?', '["The frame line: 41.409 and 91.123 MPa.", "The ceiling line: K two thirds, FP 78.695.", "The prognosis line: onset 120 m in a section that drilled quiet.", "The trend line: fit residuals of exactly zero through all twelve of the fitted shale picks."]'::jsonb, 2, 'An onset of 120 m in known-normal section is unsurvivable in review. The honest author would have caught it at the trend defence step, before any summary existed.'),
  ('porepressure', 'intermediate', 'module', 'm06-the-prognosis-workflow', 12, 'What must accompany a quoted onset for it to be a complete statement?', '["The detection rule and its settings.", "The name of the interpreter.", "The fracture pressure at the same depth.", "The Bowers cross-check value."]'::jsonb, 0, 'An onset is depth plus rule plus settings: threshold, grid, exponent. Without them, a colleague with different settings can contradict you about a well you agree on.'),
  ('porepressure', 'intermediate', 'module', 'm06-the-prognosis-workflow', 13, 'Which check would catch a submission whose pp_td and op_td differ by 41.2 MPa instead of the hydrostatic''s 41.408579625?', '["The slope check, which reads the pressure gradient between the two quoted depths.", "The quiet-section check.", "The loop closure.", "The identity check: pp minus op must equal the hydrostatic exactly."]'::jsonb, 3, 'The two fields are not independent: their difference IS the frame''s hydrostatic. A 0.2 MPa mismatch flags a transcription or rounding slip immediately.'),
  ('porepressure', 'intermediate', 'module', 'm06-the-prognosis-workflow', 14, 'How should hand arithmetic be rounded when chasing the 0.01 MPa fields?', '["Round every intermediate value to three decimal places so the chain stays reproducible by hand.", "Carry intermediates at full precision; round only what you report.", "Round the exponentials up and the cubes down to cancel.", "Use two decimals throughout, matching the tolerance."]'::jsonb, 1, 'The chain''s exponential and cube drift if rounded mid-stream. The engine''s long values are what it holds, not a demand on your typing; three reported decimals clears the window.'),
  ('porepressure', 'intermediate', 'module', 'm06-the-prognosis-workflow', 15, 'What makes the workflow''s ordering a dependency chain rather than a style preference?', '["Convention: the industry standardised the order in 1975.", "The grading form presents the fields in that order.", "Each step consumes the previous one''s output, so rearranging breaks inputs.", "Software menus in the standard interpretation packages enforce the sequence mechanically."]'::jsonb, 2, 'Rearranging breaks inputs, not aesthetics. Reviews that start at the report work backward down the same chain to the first step that cannot defend itself.'),
  ('porepressure', 'intermediate', 'final', null, 1, 'State the Eaton relation for pore pressure in its working form.', '["PP = S - (S - Ph)(dtn/dt)^n.", "PP = Ph + (S - Ph)(dtn/dt)^n.", "PP = S - (S - Ph)(dt/dtn)^n.", "PP = S(1 - (dtn/dt)^n)."]'::jsonb, 0, 'Overburden minus the grains'' retained share of the budget. Option two adds the retained share to the hydrostatic, which double-counts; option three inverts the ratio.'),
  ('porepressure', 'intermediate', 'final', null, 2, 'The capstone specifies which trend for the graded run?', '["The exact fit through the twelve shale picks.", "The well''s own header trend, 656/220/0.0006.", "Either trend, provided it is stated.", "A regional trend imported from offset wells."]'::jsonb, 1, 'The graded values all derive from the header trend, which on this synthetic well is the true normal by construction.'),
  ('porepressure', 'intermediate', 'final', null, 3, 'What is the pore pressure at 3000 m on capstone settings?', '["31.307730125 MPa.", "35.523412418439044 MPa.", "33.307730125 MPa.", "36.8329425 MPa."]'::jsonb, 2, 'Hydrostatic plus exactly 2 MPa of ramp. The 31.31 value is the bare hydrostatic and 35.52 is the stress budget there.'),
  ('porepressure', 'intermediate', 'final', null, 4, 'What is the overpressure at 3500 m, and why is it exact?', '["4 MPa: the 4 kPa per metre ramp acting over the 1000 m below 2500 m.", "3.5 MPa: overpressure scales in proportion to the total depth below the mudline.", "6 MPa: the ramp saturates at its TD value.", "2 MPa: the graded mid-ramp value."]'::jsonb, 0, 'The encoding is linear from the ramp top. 2 MPa belongs to 3000 m; the prognosis recovers each exactly.'),
  ('porepressure', 'intermediate', 'final', null, 5, 'The ratio at TD is 0.9580337483265022. What is its cube?', '["0.9436991025399956.", "0.8793108342707514.", "0.9059797014636933.", "0.9178286629325279."]'::jsonb, 1, 'The other values are the cube at 3000 m, the cube at 3500 m, and the SQUARE at TD.'),
  ('porepressure', 'intermediate', 'final', null, 6, 'Which statement about the onset is fully correct?', '["The ramp starts at 2500 m and the detection rule, applied on the sample grid, reports 2500 m exactly.", "The ramp starts at 2520 m and the rule reports it exactly.", "The ramp starts at 2500 m; the rule reports 2520 m at n 3.", "The rule reports 2510 m, where overpressure first exists."]'::jsonb, 2, 'Overpressure at 2510 m is a real 0.04 MPa but under threshold. The graded onset is the rule''s output, tolerance zero.'),
  ('porepressure', 'intermediate', 'final', null, 7, 'At n = 1 on the well trend, the detected onset moves to which depth?', '["2500 m.", "2510 m.", "2520 m.", "2540 m."]'::jsonb, 3, 'The quieter anomaly needs more ramp to clear 0.05 MPa: 0.0133 MPa per sample at n 1 reaches the bar at 2540. At n 4 and 5 it fires at 2510.'),
  ('porepressure', 'intermediate', 'final', null, 8, 'Why does the exponent move the DETECTED onset but not the real one?', '["Because the detection rule consults the exponent directly when it sets its own working threshold.", "The ratio leaves 1 at the same sample for every n, while the anomaly''s growth rate scales with n.", "Because the grid spacing changes with the exponent.", "Because the real onset is defined at the threshold depth."]'::jsonb, 1, 'Above the ramp top, 1 to any power is 1. Below it, the same departure is read louder or quieter, crossing the fixed threshold sooner or later.'),
  ('porepressure', 'intermediate', 'final', null, 9, 'The worst gap between recovered overpressure and the encoded ramp, on capstone settings, is closest to which value?', '["2.2e-8 Pa.", "0.01 MPa.", "2.2e-8 MPa.", "0.4 kPa."]'::jsonb, 0, 'Twenty-two billionths of a pascal: floating-point residue. The units matter; 2.2e-8 MPa would be a thousand times larger.'),
  ('porepressure', 'intermediate', 'final', null, 10, 'What does the closed loop NOT certify?', '["That the engine implements the pipeline it claims, with no hidden smoothing or unit conversion anywhere.", "That inverse-then-forward is the identity on this data.", "That your matching hand chain is the same mathematics.", "That real shale converts stress to slowness by a cube law."]'::jsonb, 3, 'The loop closes because the well was built from the equation. Geology is exactly what a self-referential fixture cannot certify.'),
  ('porepressure', 'intermediate', 'final', null, 11, 'A prognosis shows pore pressure crossing ABOVE the fracture pressure curve at 3200 m. What does the ordering check conclude?', '["The well simply needs an additional casing string set at 3200 m.", "Something upstream is broken: the ordering is physics.", "The exponent should be lowered until the curves separate.", "The fracture pressure needs a higher K."]'::jsonb, 1, 'Hydrostatic, pore, fracture, overburden must order at every depth of a healthy prognosis. A violation is a bug hunt, not an interpretation.'),
  ('porepressure', 'intermediate', 'final', null, 12, 'The pore pressure curve below the onset runs straight at 14.1 kPa per metre. What are its two components?', '["10.1 hydrostatic gradient plus 4.0 of ramp.", "9.8 gravity plus 4.3 of compaction.", "6.0 overpressure plus 8.1 of budget.", "12.07 percent of the local overburden gradient at that depth."]'::jsonb, 0, '1030 kg/m3 times g gives 10.1008495 kPa per metre; the encoded mechanism adds exactly 4. Slopes decompose, and reading them is a QC skill.'),
  ('porepressure', 'intermediate', 'final', null, 13, 'Which error family enters overpressure through the budget factor?', '["Shale-pick bias inside the compaction trend fit.", "Sonic tool miscalibration.", "Density log bias in the overburden.", "A wrong exponent."]'::jsonb, 2, 'OP is budget times fraction. Density errors move the budget; trend, sonic and exponent errors move the fraction. Percentage errors add across the product.'),
  ('porepressure', 'intermediate', 'final', null, 14, 'The fitted trend differs from the header by 6 us/m at the mudline and a sixth in decay. What does it do to the TD pore pressure?', '["Moves it under 1 MPa, since the trends converge at depth.", "Raises it 6.429177480013587 MPa, to 53.83775710501359.", "Lowers it, since the fitted trend is steeper.", "Raises it exactly 2.07 MPa, the ratio of the trends."]'::jsonb, 1, 'The low trend biases every ratio down; the exponent triples the bias and the budget scales it. The 2.07 is the overpressure FACTOR at TD, not an increment.'),
  ('porepressure', 'intermediate', 'final', null, 15, 'The fitted-trend run reports overpressure from 120 m down. Which QC check convicts it?', '["The consistency identities between the quoted pressure fields and the frame values.", "The ordering check.", "The loop tile''s units.", "The quiet-section check: known-normal hole must return near-hydrostatic."]'::jsonb, 3, '1.6 MPa of claimed overpressure at 1000 m in section that drilled quiet is impossible. The identities and orderings all pass, because the wrong numbers are internally consistent.'),
  ('porepressure', 'intermediate', 'final', null, 16, 'Estimate the phantom overpressure a 3 percent low trend produces at a depth with a 40 MPa budget, at n 3.', '["About 1.2 MPa.", "About 3.6 MPa.", "About 0.4 MPa.", "About 12 MPa."]'::jsonb, 1, 'n times epsilon times budget: 3 x 0.03 x 40 = 3.6 MPa, slightly hot because linearisation overstates the cube. The screening estimate takes thirty seconds.'),
  ('porepressure', 'intermediate', 'final', null, 17, 'Why is a trend error more dangerous than a log spike of the same size?', '["Coherent across samples, amplified by the exponent, smooth in the product.", "It cannot be detected by any means.", "It only affects the fracture pressure.", "It reverses sign with depth in a way that defeats any averaging over the interval."]'::jsonb, 0, 'Systematic, amplified, invisible in the product: caught at the input by defending the trend, or not at all.'),
  ('porepressure', 'intermediate', 'final', null, 18, 'What did the two-trend design of this synthetic well exist to teach?', '["That least-squares fitting of exponential trends is numerically unstable at twelve points.", "That twelve picks are too few for a fit.", "A perfect fit to misleading picks is still the wrong normal; the trend is the method''s largest decision.", "That header values always outrank measured data."]'::jsonb, 2, 'The fit was exact and wrong. On a real well the same trap has no answer key, which is why the defence checklist exists.'),
  ('porepressure', 'intermediate', 'final', null, 19, 'Which observation would settle the trend argument on a real well shaped like this one?', '["A measured formation pressure inside the anomalous section.", "A second, independent least-squares fit through the same twelve shale picks.", "A smoother version of the same sonic.", "A higher-order trend polynomial."]'::jsonb, 0, 'The candidates'' predictions separate by megapascals at depth; one measured point discriminates. Refitting the same picks reproduces the same bias.'),
  ('porepressure', 'intermediate', 'final', null, 20, 'With nu = 0.4, the fracture pressure at TD is 76.55157117548856 MPa. Which one-line check verifies it?', '["Two thirds of the overburden plus one third of the pore pressure.", "Two thirds of the budget plus the overburden.", "The pore pressure plus half the budget.", "The overburden minus the hydrostatic, multiplied by the coefficient K."]'::jsonb, 0, 'The mixture form: 60.749 plus 15.803. Any point of the ceiling is one line of arithmetic from two trusted numbers.'),
  ('porepressure', 'intermediate', 'final', null, 21, 'How does the fracture pressure respond when overpressure raises the pore pressure?', '["It falls, since the rock is weakened.", "It rises, by one third of the pore pressure increase.", "It is unchanged: the ceiling depends only on the overburden.", "It rises one for one with the pore pressure."]'::jsonb, 1, 'FP = KS + (1-K)PP with K two thirds: the same overpressure that endangers the well from below props its ceiling up, partially.'),
  ('porepressure', 'intermediate', 'final', null, 22, 'The window FP minus PP equals what, in coefficient-form algebra?', '["(1 - K)(S - PP).", "K(S - Ph).", "K(S - PP).", "(S - PP) / K."]'::jsonb, 2, 'Two thirds of the effective stress on this well. The (1-K) expression is the margin between fracture pressure and overburden instead.'),
  ('porepressure', 'intermediate', 'final', null, 23, 'At TD the space between fracture pressure and overburden is exactly half the window below it. Why?', '["Because the ramp consumed half the window.", "Because the hydrostatic sits at exactly half the overburden by the time the well reaches TD.", "Because the sample grid is 10 m.", "Because K = 2/3 splits the effective stress two-to-one."]'::jsonb, 3, 'FP sits two thirds of the way from PP to S, so above-gap (1-K) is half the below-gap K. The factor of two IS the coefficient in disguise.'),
  ('porepressure', 'intermediate', 'final', null, 24, 'A leak-off test back-calculates K = 0.62 at a shoe where the elastic value would be 0.6667. What does calibrated practice do?', '["Adopt the elastic two-thirds value, since the derivation from Poisson''s ratio can never inflate.", "Carry the measured K, and expect it to vary with depth.", "Average the two values.", "Reject the test as inconsistent with theory."]'::jsonb, 1, 'The measured K carries the physics the derivation ignored: tectonics, anisotropy, strength, hoop effects. The formula survives; the costume of nu comes off.'),
  ('porepressure', 'intermediate', 'final', null, 25, 'Which error moves the fracture pressure but leaves the pore pressure untouched?', '["A five-point error in K.", "A density log biased light by two percent everywhere.", "A low compaction trend.", "A wrong exponent."]'::jsonb, 0, 'K enters only the ceiling. Density moves both through the overburden; trend and exponent move the floor and pass a third of it into the ceiling.'),
  ('porepressure', 'intermediate', 'final', null, 26, 'What is the fracture pressure at 3500 m, where S is 78.90215933224333 and PP is 40.358154875 MPa?', '["55.77575665789733 MPa.", "66.05415784649554 MPa.", "64.72082451316221 MPa.", "53.206156360747776 MPa."]'::jsonb, 1, 'Two thirds of 78.902 plus one third of 40.358: 52.601 plus 13.453. The distractors are the nu-as-K slip, the hydrostatic-mixture slip, and the swapped-weights slip, each computed at this depth.'),
  ('porepressure', 'intermediate', 'final', null, 27, 'Which report line is missing from: frame checked, prognosis at n 3, onset 2520 by the 0.05 rule, FP at K two thirds?', '["The trend, with its defence.", "The mud weight recommendation.", "The equivalent circulating density.", "The casing design."]'::jsonb, 0, 'The four-line summary is frame, trend, prognosis, ceiling. Mud and casing belong to the Expert tier and drilling engineering; the trend line is this tier''s and absent.'),
  ('porepressure', 'intermediate', 'final', null, 28, 'Why do the graded pressure fields carry 0.01 MPa tolerances while the trend carries 0.5 us/m?', '["Pressures are measured quantities while trends are merely computed constructions from picks.", "Deterministic chains with no interpretation once inputs are fixed; tolerance covers rounding only.", "The trend tolerance is looser because trends do not matter.", "MPa are smaller units than us/m."]'::jsonb, 1, 'Nothing in the chain is generous-worthy: with the trend, exponent and frame specified, the answer is arithmetic. Tolerances cover honest rounding, not disagreement.'),
  ('porepressure', 'intermediate', 'final', null, 29, 'On this well, what fraction of the TD stress budget does the fluid take at capstone settings?', '["0.1206891657292486.", "0.8793108342707514.", "0.0563008974600044.", "0.0940202985363067."]'::jsonb, 0, 'One minus the cubed ratio. The complements and the 3000 m and 3500 m fractions make the distractors; know which is which.'),
  ('porepressure', 'intermediate', 'final', null, 30, 'Which velocity corresponds to the TD sample''s transit time of 270.92263512383806 us/m?', '["3358.333032825104 m/s.", "2905.6972280296195 m/s.", "3691.0906301457703 m/s.", "4000.0 m/s."]'::jsonb, 2, 'One million over the transit time. The 3358 value belongs to the 3000 m sample; the Expert tier''s Bowers work consumes this conversion.'),
  ('porepressure', 'intermediate', 'final', null, 31, 'What would a pore pressure prognosis show if the sonic were fed through Eaton in a thick gas-charged sand?', '["Nothing anomalous, because sonic tools are compensated for pore-fluid effects by design.", "A large phantom spike: gas slowness reads as pore pressure.", "Pressures below hydrostatic, since gas stiffens rock.", "An engine exception at the gas contact."]'::jsonb, 1, 'A few percent of gas collapses velocity; the ratio converts every excess microsecond to pressure. Screening by lithology and resistivity is the defence, and sands are off-trend anyway.'),
  ('porepressure', 'intermediate', 'final', null, 32, 'The three-stage error estimate is Delta OP = n epsilon (S - Ph). Which stage does the exponent own?', '["Converting the raw trend error into an equally sized ratio error.", "Multiplying the ratio error by roughly n.", "Scaling percent into megapascals.", "Setting the sign of the error."]'::jsonb, 1, 'Stage one is one-for-one into the ratio; stage three is the budget''s. The middle stage is the same amplification that makes the method sensitive to signal.'),
  ('porepressure', 'intermediate', 'final', null, 33, 'What distinguishes the quiet-section check from the loop check?', '["The quiet check uses drilling history as rough pressure data; the loop compares explicit ground truth.", "They are the same closure applied at two different depths of the same curve.", "The quiet check needs the fracture pressure; the loop does not.", "The loop check runs before the prognosis; the quiet check after."]'::jsonb, 0, 'Both are closures of different strength: quiet sections certify the trend cheaply everywhere; the loop certifies everything wherever truth exists.'),
  ('porepressure', 'intermediate', 'final', null, 34, 'An interpreter proposes reporting the onset as 2500 m because that is where the mechanism starts. What is the correct objection?', '["2500 m does not sit on the 10 m sample grid of this well.", "The mechanism starts at 2520 m.", "The graded onset is the rule''s output; report the rule with the depth.", "Onsets are always reported one sample deep."]'::jsonb, 2, 'Both statements can be reported together: mechanism at 2500 by construction, rule output 2520. What is not acceptable is quoting either without saying which it is.'),
  ('porepressure', 'intermediate', 'final', null, 35, 'How much overpressure remains at TD if the exponent is dropped to 2?', '["4.085105895179361 MPa.", "2.0863306869306193 MPa.", "7.834533176889628 MPa.", "6 MPa, unchanged."]'::jsonb, 0, 'The n table: 2.09, 4.09, 6, 7.83, 9.59 for n 1 through 5. Each step buys less than the last.'),
  ('porepressure', 'intermediate', 'final', null, 36, 'Why is the n-step gain shrinking, 2.00 then 1.91 then 1.83 then 1.76 MPa?', '["The stress budget itself shrinks as the exponent grows, capping what any n can hand over.", "Floating point saturates near 6 MPa.", "The detection threshold absorbs the difference.", "Each increment multiplies the surviving fraction by another factor of r."]'::jsonb, 3, 'Overpressure is bounded by the budget; the lever saturates as the retained share decays geometrically.'),
  ('porepressure', 'intermediate', 'final', null, 37, 'A candidate computes the hydrostatic at 3000 m with g = 9.81 while chasing the 0.01 MPa fields. What happens?', '["Nothing: the tolerance was chosen to absorb both common roundings of gravity without penalty.", "The hydrostatic lands about 0.01 MPa high, consuming the tolerance before the chain begins.", "The error cancels in the ratio.", "The overburden compensates automatically."]'::jsonb, 1, 'The Associate lesson stays load-bearing: rounded g shifts the reference the graded pressures stand on. Use 9.80665, always.'),
  ('porepressure', 'intermediate', 'final', null, 38, 'Which pair of depths does the capstone grade the pore pressure chain at?', '["2500 m and 4000 m.", "2520 m and 3500 m.", "3000 m and 4000 m.", "3000 m and 3500 m."]'::jsonb, 2, 'One mid-ramp point and the boundary: 33.307730125 and 47.408579625 MPa. The chain is identical; only the sample changes.'),
  ('porepressure', 'intermediate', 'final', null, 39, 'The trend at TD evaluates to 220 plus 436 times e to the minus 2.4. Which value of the exponential is correct?', '["0.09071795328941251.", "0.16529888822158656, as at 3000 m.", "0.1224564282529819.", "0.5488116360940264."]'::jsonb, 0, 'The others are e to the minus 1.8, minus 2.1 and minus 0.6, the exponentials at 3000 m, 3500 m and 1000 m.'),
  ('porepressure', 'intermediate', 'final', null, 40, 'What is the honest statement about interpolating EMW or pressures between quoted depths?', '["Interpolate the total pressures directly: totals are smoother than residuals on any physical well.", "Interpolate the overpressure residual and recompute the reference at the target depth.", "Never interpolate: always rerun the engine.", "Interpolate in log space for stability."]'::jsonb, 1, 'Residuals survive interpolation; totals drift when the reference bends. On this well totals happen to work, which is a property of this well, not a licence.'),
  ('porepressure', 'intermediate', 'final', null, 41, 'A report quotes: pore pressure 47.41 MPa at TD, trend defended, ramp recovered to 1e-8 Pa, K calibrated at the shoe. A reviewer asks one thing more before signing. What?', '["The sensitivity declarations: trend spread, exponent leverage, K leverage.", "The version identifier of the software package that ran the chain.", "A finer sample grid.", "The colour scheme of the pressure plot."]'::jsonb, 0, 'A single curve without its sensitivities claims precision its inputs lack. Declaring the spreads is what converts a curve into an honest object.'),
  ('porepressure', 'intermediate', 'final', null, 42, 'Which skill does this tier''s capstone certify that the Associate capstone could not?', '["Integrating a wireline density log into an overburden curve with the trapezoidal rule.", "Evaluating an exponential trend at depth.", "Converting a slowness anomaly into a defended pressure with onset, ceiling and closure.", "Fitting a least-squares line through picks."]'::jsonb, 2, 'The frame skills were the Associate tier''s. This tier adds the inversion, its defence, and the fracture ceiling: the parts that make it a prognosis rather than a frame.');
